function onscary(x, y, mtmp)

{
    x = C.coordxy(C.coordxy(x)); y = C.coordxy(C.coordxy(y));
    let ep;
    /* <0,0> is used by musical scaring;
     * it doesn't care about scrolls or engravings or dungeon branch */
    let auditory_scare = (C.char(C.bool(x == 0 && y == 0))),
            magical_scare = C.char(!auditory_scare);

    /* creatures who are directly resistant to any type of scaring:
     * Rodney, lawful minions, Angels, the Riders */
    if (C.bool(C.bool(C.bool(mtmp.iswiz || C.is_lminion(mtmp)) || C.samePtr(mtmp.data, C.mons[C.PM_ANGEL]))
        || C.is_rider(mtmp.data)))
        return 0;

    /* creatures who are directly resistant to magical scaring
     * based on the mere presence of something at a location:
     * humans etc.
     * uniques have ascended their base monster instincts */
    if (C.bool(magical_scare
        && (C.bool(mtmp.data.mlet == C.S_HUMAN || C.unique_corpstat(mtmp.data)))))
        return 0;

    /* creatues who resist scaring under particular circumstances:
     * shopkeepers inside their own shop
     * priests inside their own temple */
    if (C.bool((C.bool(mtmp.isshk && C.inhishop(mtmp)))
        || (C.bool(mtmp.ispriest && C.inhistemple(mtmp)))))
        return 0;

    if (auditory_scare)
        return 1;

    /* should this still be true for defiled/molochian altars? */
    if (C.bool(C.IS_ALTAR(C.levl[x][y].typ)
        && (C.bool(mtmp.data.mlet == C.S_VAMPIRE || C.is_vampshifter(mtmp)))))
        return 1;

    /* the scare monster scroll doesn't have any of the below
     * restrictions, being its own source of power */
    if (C.sobj_at(C.SCR_SCARE_MONSTER, x, y))
        return 1;

    /*
     * Creatures who don't (or can't) fear a written Elbereth:
     * all the above plus shopkeepers (even if poly'd into non-human),
     * vault guards (also even if poly'd), blind or peaceful monsters,
     * humans and elves, and minotaurs.
     *
     * If the player isn't actually on the square OR the player's image
     * isn't displaced to the square, no protection is being granted.
     *
     * Elbereth doesn't work in Gehennom, the Elemental Planes, or the
     * Astral Plane; the influence of the Valar only reaches so far.
     */
    return (C.bool(C.bool((ep = C.sengr_at("Elbereth", x, y, 1)) != 0
            && (C.bool(C.bool(C.u_at(x, y)
                || (C.bool(C.bool(C.Displaced && mtmp.mux == x) && mtmp.muy == y)))
                || (C.bool(ep.guardobjects && C.vobj_at(x, y))))))
            && !(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(mtmp.isshk || mtmp.isgd) || !mtmp.mcansee)
                 || mtmp.mpeaceful)
                 || C.samePtr(mtmp.data, C.mons[C.PM_MINOTAUR]))
                 || C.Inhell) || C.In_endgame(C.u.uz)))));
}

/* regenerate lost hit points */
function mon_regen(mon, digest_meal)

{
    digest_meal = C.char(C.boolean(digest_meal));
    if (C.bool(C.svm.moves % 20n == 0 || C.regenerates(mon.data)))
        C.healmon(mon, 1, 0);
    if (mon.mspec_used)
        mon.mspec_used--;
    if (digest_meal) {
        if (mon.meating) {
            mon.meating--;
            if (mon.meating <= 0)
                C.finish_meating(mon);
        }
    }
}

/*
 * Possibly awaken the given monster.  Return a 1 if the monster has been
 * jolted awake.
 */
function disturb(mtmp)

{
    /*
     * + Ettins are hard to surprise.
     * + Nymphs, jabberwocks, and leprechauns do not easily wake up.
     *
     * Wake up if:
     *  in direct LOS                                           AND
     *  within 10 squares                                       AND
     *  not stealthy or (mon is an ettin and 9/10)              AND
     *  (mon is not a nymph, jabberwock, or leprechaun) or 1/50 AND
     *  Aggravate or mon is (dog or human) or
     *      (1/7 and mon is not mimicking furniture or object)
     */
    if (C.bool(C.bool(C.bool(C.bool(C.couldsee(mtmp.mx, mtmp.my) && C.mdistu(mtmp) <= 100)
        && (C.bool(!C.Stealth || (C.bool(C.samePtr(mtmp.data, C.mons[C.PM_ETTIN]) && C.rn2(10, 342, "disturb"))))))
        && (C.bool(!(C.bool(C.bool(mtmp.data.mlet == C.S_NYMPH
              || C.samePtr(mtmp.data, C.mons[C.PM_JABBERWOCK]))
/* DEFERRED */

              || mtmp.data.mlet == C.S_LEPRECHAUN)) || !C.rn2(50, 348, "disturb"))))
        && (C.bool(C.bool(C.Aggravate_monster
            || (C.bool(mtmp.data.mlet == C.S_DOG || mtmp.data.mlet == C.S_HUMAN)))
            || (C.bool(C.bool(!C.rn2(7, 351, "disturb") && C.M_AP_TYPE(mtmp) != C.M_AP_FURNITURE)
                && C.M_AP_TYPE(mtmp) != C.M_AP_OBJECT)))))) {
        C.wake_msg(mtmp, !mtmp.mpeaceful);
        mtmp.msleeping = 0;
        return 1;
    }
    return 0;
}

/* ungrab/expel held/swallowed hero */
function release_hero(mon)

{
    if (C.samePtr(mon, C.u.ustuck)) {
        if (C.u.uswallow) {
            C.expels(mon, mon.data, 1);
        } else if (!C.sticks(C.gy.youmonst.data)) {
            C.unstuck(mon); /* let go */
            C.You("get released!");
        }
    }
}

function find_pmmonst(pm)

{
    pm = C.int(C.int(pm));
    let mtmp = 0;

    if ((C.svm.mvitals[pm].mvflags & C.G_GENOD) == 0)
        for (mtmp = C.fmon; mtmp; mtmp = mtmp.nmon) {
            if (C.DEADMONSTER(mtmp))
                continue;
            if (C.samePtr(mtmp.data, C.mons[pm]))
                break;
        }

    return mtmp;
}

/* killer bee 'mon' is on a spot containing lump of royal jelly 'obj' and
   will eat it if there is no queen bee on the level; return 1: mon died,
   0: mon ate jelly and lived; -1: mon didn't eat jelly to use its move */
function bee_eat_jelly(mon, obj)

{
    let m_delay;
    let mtmp = find_pmmonst(C.PM_QUEEN_BEE);

    /* if there's no queen on the level, eat the royal jelly and become one */
    if (!mtmp) {
        m_delay = C.int(obj.blessed ? 3 : !obj.cursed ? 5 : 7);
        if (obj.quan > 1n)
            obj = C.splitobj(obj, 1n);
        if (C.canseemon(mon))
            C.pline_mon(mon, "%s eats %s.", C.Monnam(mon), C.an(C.xname(obj)));
        C.delobj(obj);

        if (C.int(mon.m_lev) < C.mons[C.PM_QUEEN_BEE].mlevel - 1)
            mon.m_lev = C.uchar((C.mons[C.PM_QUEEN_BEE].mlevel - 1));
        /* there should be delay after eating, but that's too much
           hassle; transform immediately, then have a short delay */
        C.grow_up(mon, 0);

        if (C.DEADMONSTER(mon))
            return 1; /* dead; apparently queen bees have been genocided */
        mon.mfrozen = m_delay, mon.mcanmove = 0;
        return 0; /* bee used its move */
    }
    return -1; /* a queen is already present; ordinary bee hasn't moved yet */
}

/* gelatinous cube eats something from its inventory */
function gelcube_digests(mtmp)

{
    let otmp = mtmp.minvent;

    if (C.bool(mtmp.meating || !mtmp.minvent))
        return -1;

    while (otmp) {
        if (C.bool(C.bool(C.bool(C.is_organic(otmp) && !otmp.oartifact)
            && !C.is_mines_prize(otmp)) && !C.is_soko_prize(otmp)))
            break;
        otmp = otmp.nobj;
    }

    if (!otmp)
        return -1;

    mtmp.meating = C.eaten_stat(mtmp.meating, otmp);
    C.extract_from_minvent(mtmp, otmp, 1, 1);
    C.m_consume_obj(mtmp, otmp);
    return 0; /* used a move */
}


/* FIXME: gremlins don't flee from monsters wielding Sunsword or wearing
   gold dragon scales/mail, nor from gold dragons, only from the hero */



/* monster begins fleeing for the specified time, 0 means untimed flee
 * if first, only adds fleetime if monster isn't already fleeing
 * if fleemsg, prints a message about new flight, otherwise, caller should */
function monflee(mtmp, fleetime, first, fleemsg)

{
    fleetime = C.int(C.int(fleetime)); first = C.char(C.boolean(first)); fleemsg = C.char(C.boolean(fleemsg));
    /* shouldn't happen; maybe warrants impossible()? */
    if (C.DEADMONSTER(mtmp))
        return;

    if (C.samePtr(mtmp, C.u.ustuck))
        release_hero(mtmp); /* expels/unstuck */

    if (C.bool(!first || !mtmp.mflee)) {
        /* don't lose untimed scare */
        if (!fleetime)
            mtmp.mfleetim = 0;
        else if (C.bool(!mtmp.mflee || mtmp.mfleetim)) {
            fleetime = C.int(fleetime + (C.int(mtmp.mfleetim)));
            /* ensure monster flees long enough to visibly stop fighting */
            if (fleetime == 1)
                fleetime++;
            mtmp.mfleetim = C.uint(C.min(fleetime, 127));
        }
        if (C.bool(C.bool(C.bool(C.bool(!mtmp.mflee && fleemsg) && C.canseemon(mtmp))
            && C.M_AP_TYPE(mtmp) != C.M_AP_FURNITURE)
            && C.M_AP_TYPE(mtmp) != C.M_AP_OBJECT)) {
            /* unfortunately we can't distinguish between temporary
               sleep and temporary paralysis, so both conditions
               receive the same alternate message */
            if (C.bool(!mtmp.mcanmove || !mtmp.data.mmove)) {
                C.pline_mon(mtmp, "%s seems to flinch.",
                          C.Adjmonnam(mtmp, "immobile"));
            } else if ((C.bool(C.bool(C.bool(C.samePtr(mtmp.data,C.mons[C.PM_GREMLIN]) && (C.bool((C.bool(C.bool(C.uwep && C.uwep.lamplit) && C.artifact_light(C.uwep))) || (C.bool(C.bool(C.uarm && C.uarm.lamplit) && C.artifact_light(C.uarm)))))) && mtmp.mcansee) && C.couldsee(mtmp.mx,mtmp.my)))) {
                if (C.Unaware) {
                    /* tell the player even if the hero is unconscious */
                    C.pline_mon(mtmp, "%s is frightened.", C.Monnam(mtmp));
                } else if (C.bool(C.rn2(10, 499, "monflee") || C.Deaf)) {
                    /* via flees_light(), will always be either via uwep
                       (Sunsword) or uarm (gold dragon scales/mail) or both;
                       TODO? check for both and describe the one which is
                       emitting light with a bigger radius */
                    let lsrc = (C.bool(C.uwep && C.artifact_light(C.uwep)))
                                       ? C.bare_artifactname(C.uwep)
                                       : (C.bool(C.uarm && C.artifact_light(C.uarm)))
                                         ? C.yname(C.uarm)
                                         : "[its imagination?]";

                    C.pline_mon(mtmp, "%s flees from the painful light of %s.",
                          C.Monnam(mtmp), lsrc);
                } else {
                    
                    C.verbalize("Bright light!");
                }
            } else {
                C.pline_mon(mtmp, "%s turns to flee.", C.Monnam(mtmp));
            }
        }

        if (C.bool(C.samePtr(mtmp.data, C.mons[C.PM_VROCK]) && !mtmp.mspec_used)) {
            mtmp.mspec_used = 75 + C.rn2(25, 522, "monflee");
            C.create_gas_cloud(mtmp.mx, mtmp.my, 5, 8);
        }

        mtmp.mflee = 1;
    }
    /* ignore recently-stepped spaces when made to flee */
    mon_track_clear(mtmp);
}

function distfleeck(mtmp, inrange, nearby, scared)
 /* output */
{
    let seescaryx, seescaryy;
    let sawscary = C.char(0), bravegremlin = (C.char(C.rn2(5, 538, "distfleeck") == 0));

    inrange.value = (C.dist2(mtmp.mx, mtmp.my, mtmp.mux, mtmp.muy)
                <= (C.BOLT_LIM * C.BOLT_LIM));
    nearby.value = C.bool(inrange.value && C.monnear(mtmp, mtmp.mux, mtmp.muy));

    /* Note: if your image is displaced, the monster sees the Elbereth
     * at your displaced position, thus never attacking your displaced
     * position, but possibly attacking you by accident.  If you are
     * invisible, it sees the Elbereth at your real position, thus never
     * running into you by accident but possibly attacking the spot
     * where it guesses you are.
     */
    if (C.bool(!mtmp.mcansee || (C.bool(C.Invis && !C.perceives(mtmp.data))))) {
        seescaryx = C.int(mtmp.mux);
        seescaryy = C.int(mtmp.muy);
    } else {
        seescaryx = C.int(C.u.ux);
        seescaryy = C.int(C.u.uy);
    }

    sawscary = C.char(onscary(seescaryx, seescaryy, mtmp));
    if (C.bool(nearby.value && (C.bool(C.bool(sawscary
                    || (C.bool((C.bool(C.bool(C.bool(C.samePtr(mtmp.data,C.mons[C.PM_GREMLIN]) && (C.bool((C.bool(C.bool(C.uwep && C.uwep.lamplit) && C.artifact_light(C.uwep))) || (C.bool(C.bool(C.uarm && C.uarm.lamplit) && C.artifact_light(C.uarm)))))) && mtmp.mcansee) && C.couldsee(mtmp.mx,mtmp.my))) && !bravegremlin)))
                    || (C.bool(!mtmp.mpeaceful && C.in_your_sanctuary(mtmp, 0, 0))))))) {
        scared.value = 1;
        monflee(mtmp, C.rnd(C.rn2(7, 564, "distfleeck") ? 10 : 100, 564, "distfleeck"), 1, 1);
    } else
        scared.value = 0;
}


