/* a mind flayer unleashes a mind blast  */
function mind_blast(mtmp)

{
    let m2, nmon = 0;

    if (C.canseemon(mtmp))
        C.pline_mon(mtmp, "%s concentrates.", C.Monnam(mtmp));
    if (C.mdistu(mtmp) > C.BOLT_LIM * C.BOLT_LIM) {
        C.You("sense a faint wave of psychic energy.");
        return;
    }
    C.pline("A wave of psychic energy pours over you!");
    if (C.bool(mtmp.mpeaceful
        && (C.bool(!C.Conflict || C.resist_conflict(mtmp))))) {
        C.pline("It feels quite soothing.");
    } else if (!C.u.uinvulnerable) {
        let dmg;
        let m_sen = C.char(C.sensemon(mtmp));

        if (C.bool(C.bool(m_sen || (C.bool(C.Blind_telepat && C.rn2(2, 601, "mind_blast")))) || !C.rn2(10, 601, "mind_blast"))) {
            /* hiding monsters are brought out of hiding when hit by
                a psychic blast, so do the same for hiding poly'd hero */
            if (C.u.uundetected) {
                C.u.uundetected = 0;
                C.newsym(C.u.ux, C.u.uy);
            } else if (C.bool(C.U_AP_TYPE != C.M_AP_NOTHING
                        /* hero has no way to hide as monster but
                            check for that theoretical case anyway */
                        && C.U_AP_TYPE != C.M_AP_MONSTER)) {
                C.gy.youmonst.m_ap_type = C.M_AP_NOTHING;
                C.gy.youmonst.mappearance = 0;
                C.newsym(C.u.ux, C.u.uy);
            }
            C.pline("It locks on to your %s!",
                    m_sen ? "telepathy"
                    : C.Blind_telepat ? "latent telepathy"
                    : "mind"); /* note: hero is never mindless */
            dmg = C.int(C.rnd(15, 619, "mind_blast"));
            if (C.Half_spell_damage)
                dmg = C.int(C.intdiv(dmg + 1, 2));
            C.losehp(dmg, "psychic blast", C.KILLED_BY_AN);
        }
    }
    for (m2 = C.fmon; m2; m2 = nmon) {
        nmon = m2.nmon;
        if (C.DEADMONSTER(m2))
            continue;
        if (m2.mpeaceful == mtmp.mpeaceful)
            continue;
        if (C.mindless(m2.data))
            continue;
        if (C.samePtr(m2, mtmp))
            continue;
        if (C.bool((C.bool(C.telepathic(m2.data) && (C.bool(C.rn2(2, 635, "mind_blast") || m2.mblinded)))) || !C.rn2(10, 635, "mind_blast"))) {
            /* wake it up first, to bring hidden monster out of hiding */
            C.wakeup(m2, 0);
            if (C.cansee(m2.mx, m2.my))
                C.pline("It locks on to %s.", C.mon_nam(m2));
            m2.mhp -= C.rnd(15, 640, "mind_blast");
            if (C.DEADMONSTER(m2))
                C.monkilled(m2, "", C.AD_DRIN);
        }
    }
}

/* called every turn for each living monster on the map, and the hero;
   caller makes sure that we're not called for DEADMONSTER() */
function m_everyturn_effect(mtmp)

{
    let is_u = C.char((C.samePtr(mtmp, C.gy.youmonst)) ? 1 : 0);
    let x = C.coordxy(is_u ? C.u.ux : mtmp.mx),
            y = C.coordxy(is_u ? C.u.uy : mtmp.my);

    if (C.samePtr(mtmp.data, C.mons[C.PM_FOG_CLOUD])) {
        /* don't leave a vapor cloud if some other gas cloud is already
           present, or when flowing under closed doors so that visibility
           changes aren't mixed with messages about doing such */
        if (C.bool(!closed_door(x, y) && !C.visible_region_at(x, y)))
            C.create_gas_cloud(x, y, 1, 0); /* harmless vapor */
    }
}

/* do whatever effects monster has after moving.
   called for both monsters and polyed hero.
   for hero, called after location changes,
   to prevent spam messages for hero getting enveloped in a cloud.
   for monsters, called before location changes,
   because monsters don't have "previous location" field */
function m_postmove_effect(mtmp)

{
    let is_u = C.char((C.samePtr(mtmp, C.gy.youmonst)) ? 1 : 0);
    let x = C.coordxy(is_u ? C.u.ux0 : mtmp.mx),
            y = C.coordxy(is_u ? C.u.uy0 : mtmp.my);

    /* Hezrous create clouds of stench. This does not cost a move. */
    if (C.samePtr(mtmp.data, C.mons[C.PM_HEZROU])) /* stench */
        C.create_gas_cloud(x, y, 1, 8);
    else if (C.bool(C.samePtr(mtmp.data, C.mons[C.PM_STEAM_VORTEX]) && !mtmp.mcan))
        C.create_gas_cloud(x, y, 1, 0); /* harmless vapor */
}

/* returns 1 if monster died moving, 0 otherwise */
/* The whole dochugw/m_move/distfleeck/mfndpos section is serious spaghetti
 * code. --KAA
 */
function dochug(mtmp)

{
    let mdat;
    let status = C.int(C.MMOVE_NOTHING);
    const inrange=C.intLocal(), nearby=C.intLocal(), scared=C.intLocal(); let res;
    let otmp;
    let panicattk = C.char(0);

    /*
     * PHASE ONE: Pre-movement adjustments
     */

    mdat = mtmp.data;

    if (mtmp.mstrategy & C.STRAT_ARRIVE) {
        res = C.int(m_arrival(mtmp));
        if (res >= 0)
            return res;
    }
    /* check for waitmask status change */
    if (C.bool((mtmp.mstrategy & C.STRAT_WAITFORU)
        && (C.bool(C.m_canseeu(mtmp) || mtmp.mhp < mtmp.mhpmax))))
        mtmp.mstrategy &= ~C.STRAT_WAITFORU;

    /* update quest status flags */
    C.quest_stat_check(mtmp);

    if (C.bool(!mtmp.mcanmove || (mtmp.mstrategy & C.STRAT_WAITMASK))) {
        if (C.Hallucination)
            C.newsym(mtmp.mx, mtmp.my);
        if (C.bool(C.bool(C.bool(mtmp.mcanmove && (mtmp.mstrategy & C.STRAT_CLOSE))
            && !mtmp.msleeping) && C.monnear(mtmp, C.u.ux, C.u.uy)))
            C.quest_talk(mtmp); /* give the leaders a chance to speak */
        return 0;             /* other frozen monsters can't do anything */
    }

    /* there is a chance we will wake it */
    if (C.bool(mtmp.msleeping && !disturb(mtmp))) {
        if (C.Hallucination)
            C.newsym(mtmp.mx, mtmp.my);
        return 0;
    }

    /* not frozen or sleeping: wipe out texts written in the dust */
    C.wipe_engr_at(mtmp.mx, mtmp.my, 1, 0);

    /* confused monsters get unconfused with small probability */
    if (C.bool(mtmp.mconf && !C.rn2(50, 737, "dochug")))
        mtmp.mconf = 0;

    /* stunned monsters get un-stunned with larger probability */
    if (C.bool(mtmp.mstun && !C.rn2(10, 741, "dochug")))
        mtmp.mstun = 0;

    /* Some monsters teleport. Teleportation costs a turn. */
    if (C.bool(C.bool(C.bool(C.bool(mtmp.mflee && !C.rn2(40, 745, "dochug")) && C.can_teleport(mdat)) && !mtmp.iswiz)
        && !C.noteleport_level(mtmp))) {
        if (C.rloc(mtmp, C.RLOC_MSG))
            leppie_stash(mtmp);
        return 0;
    }

    /* some monsters have special abilities */
    C.m_respond(mtmp);
    if (C.DEADMONSTER(mtmp))
        return 1; /* m_respond gaze can kill medusa */

    /* fleeing monsters might regain courage */
    if (C.bool(C.bool(C.bool(mtmp.mflee && !mtmp.mfleetim) && mtmp.mhp == mtmp.mhpmax)
        && !C.rn2(25, 759, "dochug")))
        mtmp.mflee = 0;

    /* Cease conflict-induced swallow/grab if conflict has ended. Releasing
       the hero in this way uses up the monster's turn. */
    if (C.bool(C.bool(C.bool(C.samePtr(mtmp, C.u.ustuck) && mtmp.mpeaceful) && !mtmp.mconf) && !C.Conflict)) {
        release_hero(mtmp);
        return 0;
    }

    /*
     * PHASE TWO: Special Movements and Actions
     */

    /* The monster decides where it thinks you are. This call to set_apparxy()
       must be done after you move and before the monster does. The
       set_apparxy() call in m_move() doesn't suffice since the variables
       inrange, etc. all depend on stuff set by set_apparxy().
     */
    set_apparxy(mtmp);

    /* Monsters that want to acquire things may teleport, so do it before
       inrange is set. This costs a turn only if mstate is set.  */
    if (C.is_covetous(mdat)) {
        C.tactics(mtmp);
        /* tactics -> mnexto -> deal_with_overcrowding */
        if (mtmp.mstate)
            return 0;
        set_apparxy(mtmp);
    }

    /* check distance and scariness of attacks */
    distfleeck(mtmp, inrange, nearby, scared);

    /* search for and potentially use defensive or miscellaneous items. */
    if (C.find_defensive(mtmp, 0)) {
        if (C.use_defensive(mtmp) != 0)
            return 1;
    } else if (C.find_misc(mtmp)) {
        if (C.use_misc(mtmp) != 0)
            return 1;
    }

    /* Demonic Blackmail! */
    if (C.bool(C.bool(C.bool(C.bool(nearby.value && mdat.msound == C.MS_BRIBE) && mtmp.mpeaceful) && !mtmp.mtame)
        && !C.u.uswallow)) {
        if (C.bool(mtmp.mux != C.u.ux || mtmp.muy != C.u.uy)) {
            C.pline("%s whispers at thin air.",
                  C.cansee(mtmp.mux, mtmp.muy) ? C.Monnam(mtmp) : "It");

            if (C.is_demon(C.gy.youmonst.data)) {
                /* "Good hunting, brother" */
                if (!C.tele_restrict(mtmp))
                    C.rloc(mtmp, C.RLOC_MSG);
            } else {
                mtmp.minvis = mtmp.perminvis = 0;
                /* Why?  For the same reason in real demon talk */
                if (C.canseemon(mtmp))
                    C.set_msg_xy(mtmp.mx, mtmp.my);
                C.pline("%s gets angry!", C.Amonnam(mtmp));
                mtmp.mpeaceful = 0;
                C.set_malign(mtmp);
                /* since no way is an image going to pay it off */
            }
        } else if (C.demon_talk(mtmp))
            return 1; /* you paid it off */
    }

    /* the watch will look around and see if you are up to no good :-) */
    if (C.is_watch(mdat)) {
        watch_on_duty(mtmp);
    /* mind flayers can make psychic attacks! */
    } else if (C.bool(C.is_mind_flayer(mdat) && !C.rn2(20, 831, "dochug"))) {
        mind_blast(mtmp);
        set_apparxy(mtmp);
        distfleeck(mtmp, inrange, nearby, scared);
    }

    /* If monster is nearby you, and has to wield a weapon, do so.  This
     * costs the monster a move, of course.
     */
    if (C.bool(C.bool(C.bool((C.bool(!mtmp.mpeaceful || C.Conflict)) && inrange.value)
        && C.dist2(mtmp.mx, mtmp.my, mtmp.mux, mtmp.muy) <= 8)
        && C.attacktype(mdat, C.AT_WEAP))) {
        let mw_tmp;

        /* The scared check is necessary.  Otherwise a monster that is
         * one square near the player but fleeing into a wall would keep
         * switching between pick-axe and weapon.  If monster is stuck
         * in a trap, prefer ranged weapon (wielding is done in thrwmu).
         * This may cost the monster an attack, but keeps the monster
         * from switching back and forth if carrying both.
         */
        mw_tmp = C.MON_WEP(mtmp);
        if (C.bool(C.bool(!(C.bool(C.bool(scared.value && mw_tmp) && C.is_pick(mw_tmp)))
            && mtmp.weapon_check == C.NEED_WEAPON)
            && !(C.bool(C.bool(mtmp.mtrapped && !nearby.value) && C.select_rwep(mtmp))))) {
            mtmp.weapon_check = C.NEED_HTH_WEAPON;
            if (C.mon_wield_item(mtmp) != 0)
                return 0;
        }
    }

    /*
     * PHASE THREE: Now the actual movement phase
     */

    /* A killer bee may eat honey in order to turn into a queen bee,
       costing it a move. */
    if (C.bool(C.bool(C.samePtr(mdat, C.mons[C.PM_KILLER_BEE])
        /* could be smarter and deliberately move to royal jelly, but
           then we'd need to scan the level for queen bee in advance;
           avoid that overhead and rely on serendipity... */
        && (otmp = C.sobj_at(C.LUMP_OF_ROYAL_JELLY, mtmp.mx, mtmp.my)) != 0)
        && (res = C.int(bee_eat_jelly(mtmp, otmp))) >= 0))
        return res;

    if (C.bool(C.samePtr(mdat, C.mons[C.PM_GELATINOUS_CUBE])
        && (res = C.int(gelcube_digests(mtmp))) >= 0))
        return res;

    /* A monster that passes the following checks has the opportunity
       to move. Movement itself is handled by the m_move() function. */
    if (C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(!nearby.value || mtmp.mflee) || scared.value) || mtmp.mconf) || mtmp.mstun)
        || (C.bool(mtmp.minvis && !C.rn2(3, 883, "dochug"))))
        || (C.bool(C.bool(mdat.mlet == C.S_LEPRECHAUN && !C.findgold(C.gi.invent))
            && (C.bool(C.findgold(mtmp.minvent) || C.rn2(2, 885, "dochug"))))))
        || (C.bool(C.is_wanderer(mdat) && !C.rn2(4, 886, "dochug")))) || (C.bool(C.Conflict && !mtmp.iswiz)))
        || (C.bool(!mtmp.mcansee && !C.rn2(4, 887, "dochug")))) || mtmp.mpeaceful)) {

        /* Possibly cast an undirected spell if not attacking you */
        /* note that most of the time castmu() will pick a directed
           spell and do nothing, so the monster moves normally */
        /* arbitrary distance restriction to keep monster far away
           from you from having cast dozens of sticks-to-snakes
           or similar spells by the time you reach it */
        if (C.bool(!mtmp.mspec_used
            && C.dist2(mtmp.mx, mtmp.my, C.u.ux, C.u.uy) <= 49)) {
            let a;

            for (let attackIndex = 0; attackIndex < C.NATTK; attackIndex++) {
                a = mdat.mattk[attackIndex];
                if (C.bool(a.aatyp == C.AT_MAGC
                    && (C.bool(a.adtyp == C.AD_SPEL || a.adtyp == C.AD_CLRC)))) {
                    if ((C.castmu(mtmp, a, 0, 0) & C.M_ATTK_HIT)) {
                        status = C.int(C.MMOVE_DONE); /* bypass m_move() */
                        break;
                    }
                }
            }
        }

        if (!status)
            status = C.int(m_move(mtmp, 0));
        if (C.mon_offmap(mtmp))
            return 1;
        if (status != C.MMOVE_DIED)
            distfleeck(mtmp, inrange, nearby, scared); /* recalc */

        switch (status) { /* for pets, cases 0 and 3 are equivalent */
        case C.MMOVE_NOMOVES:
            if (scared.value)
                panicattk = C.char(1);
            
            /*FALLTHRU*/
        case C.MMOVE_NOTHING: /* no movement, but it can still attack you */
        case C.MMOVE_DONE: /* absolutely no movement */
            /* vault guard might have vanished */
            if (C.bool(mtmp.isgd && (C.bool(C.DEADMONSTER(mtmp) || mtmp.mx == 0))))
                return 1; /* behave as if it died */
            /* During hallucination, monster appearance should
             * still change - even if it doesn't move.
             */
            if (C.Hallucination)
                C.newsym(mtmp.mx, mtmp.my);
            break;
        case C.MMOVE_MOVED: /* monster moved */
            /* if confused grabber has wandered off, let go */
            if (C.bool(C.samePtr(mtmp, C.u.ustuck) && !C.m_next2u(mtmp)))
                C.unstuck(mtmp);
            if (C.grounded(mdat))
                C.disturb_buried_zombies(mtmp.mx, mtmp.my);
            /* Maybe it stepped on a trap and fell asleep... */
            if (C.helpless(mtmp))
                return 0;
            /* Monsters can move and then shoot on same turn;
               our hero can't.  Is that fair? */
            if (C.bool(!nearby.value
                && (C.bool(C.bool(C.ranged_attk_available(mtmp)
                            || C.attacktype(mdat, C.AT_WEAP))
                            || C.find_offensive(mtmp)))))
                break;
            /* a monster that's digesting you can move at the
             * same time -dlc
             */
            if (C.engulfing_u(mtmp))
                return C.mattacku(mtmp);
            return 0;
        case C.MMOVE_DIED: /* monster died */
            return 1;
        }
    }

    /*
     * PHASE FOUR: Standard Attacks
     */

    /* Now, attack the player if possible - one attack set per monst */
    if (C.bool(status != C.MMOVE_DONE && (C.bool(!mtmp.mpeaceful
                                 || (C.bool(C.Conflict && !C.resist_conflict(mtmp))))))) {
        if (C.bool(C.bool((C.bool((C.bool(inrange.value && !scared.value)) || panicattk)) && !C.noattacks(mdat))
            /* [is this hp check really needed?] */
            && (C.Upolyd ? C.u.mh : C.u.uhp) > 0)) {
            if (C.mattacku(mtmp))
                return 1; /* monster died (e.g. exploded) */
        }
        if (mtmp.wormno) {
            if (C.wormhitu(mtmp))
                return 1; /* worm died (poly'd hero passive counter-attack) */
        }
    }
    /* special speeches for quest monsters */
    if (C.bool(!C.helpless(mtmp) && nearby.value))
        C.quest_talk(mtmp);
    /* extra emotional attack for vile monsters */
    if (C.bool(C.bool(C.bool(C.bool(C.bool(inrange.value && mtmp.data.msound == C.MS_CUSS) && !mtmp.mpeaceful)
        && C.couldsee(mtmp.mx, mtmp.my)) && !mtmp.minvis) && !C.rn2(5, 984, "dochug")))
        C.cuss(mtmp);

    /* note: can't get here when monster is dead, so this always returns 0 */
    return (status == C.MMOVE_DIED);
}

const practical = [ "WEAPON_CLASS", "ARMOR_CLASS",
                                           "GEM_CLASS", "FOOD_CLASS", 0 ];
const magical = [ "AMULET_CLASS", "POTION_CLASS",
                                         "SCROLL_CLASS", "WAND_CLASS",
                                         "RING_CLASS",   "SPBOOK_CLASS", 0 ];

/* monster mtmp would love to take object otmp? */
function mon_would_take_item(mtmp, otmp)

{
    let pctload = C.int(C.intdiv(C.int(C.curr_mon_load(mtmp) * 100), C.max_mon_load(mtmp)));

    if (C.bool(C.samePtr(otmp, C.uball) || C.samePtr(otmp, C.uchain)))
        return 0;
    if (C.bool(mtmp.mtame && otmp.cursed))
        return 0; /* note: will get overridden if mtmp will eat otmp */
    if (C.bool(C.is_unicorn(mtmp.data) && C.objects[otmp.otyp].oc_material != C.GEMSTONE))
        return 0;
    if (C.bool(C.bool(C.bool(!C.mindless(mtmp.data) && !C.is_animal(mtmp.data)) && pctload < 75)
        && C.searches_for_item(mtmp, otmp)))
        return 1;
    if (C.bool(C.bool(C.likes_gold(mtmp.data) && otmp.otyp == C.GOLD_PIECE) && pctload < 95))
        return 1;
    if (C.bool(C.bool(C.bool(C.likes_gems(mtmp.data) && otmp.oclass == C.GEM_CLASS)
        && C.objects[otmp.otyp].oc_material != C.MINERAL) && pctload < 85))
        return 1;
    if (C.bool(C.bool(C.likes_objs(mtmp.data) && C.strchr(practical, otmp.oclass))
        && pctload < 75))
        return 1;
    if (C.bool(C.bool(C.likes_magic(mtmp.data) && C.strchr(magical, otmp.oclass))
        && pctload < 85))
        return 1;
    if (C.bool(C.bool(C.bool(C.throws_rocks(mtmp.data) && otmp.otyp == C.BOULDER)
        && pctload < 50) && !C.Sokoban))
        return 1;
    if (C.bool(C.bool(C.bool(C.samePtr(mtmp.data, C.mons[C.PM_GELATINOUS_CUBE])
        && otmp.oclass != C.ROCK_CLASS) && otmp.oclass != C.BALL_CLASS)
        && !(C.bool(otmp.otyp == C.CORPSE && C.touch_petrifies(C.mons[otmp.corpsenm])))))
        return 1;

    return 0;
}

/* monster mtmp would love to consume object otmp, without picking it up */
function mon_would_consume_item(mtmp, otmp)

{
    let ftyp;

    if (C.bool(C.bool(otmp.otyp == C.CORPSE && !C.touch_petrifies(C.mons[otmp.corpsenm]))
        && C.corpse_eater(mtmp.data)))
        return 1;

    if (C.bool(C.bool(C.bool(mtmp.mtame && C.has_edog(mtmp)) /* has_edog(): not guardian angel */
        && (ftyp = C.int(C.dogfood(mtmp, otmp))) < C.MANFOOD)
        && (C.bool(ftyp < C.ACCFOOD || C.EDOG(mtmp).hungrytime <= C.svm.moves))))
        return 1;

    return 0;
}

function itsstuck(mtmp)

{
    if (C.bool(C.bool(C.sticks(C.gy.youmonst.data) && C.samePtr(mtmp, C.u.ustuck)) && !C.u.uswallow)) {
        C.pline_mon(mtmp, "%s cannot escape from you!", C.Monnam(mtmp));
        return 1;
    }
    return 0;
}

/*
 * should_displace()
 *
 * Displacement of another monster is a last resort and only
 * used on approach. If there are better ways to get to target,
 * those should be used instead. This function does that evaluation.
 */
function should_displace(mtmp, data, ggx, ggy)

{
    ggx = C.coordxy(C.coordxy(ggx)); ggy = C.coordxy(C.coordxy(ggy));
    let shortest_with_displacing = C.int(-1);
    let shortest_without_displacing = C.int(-1);
    let count_without_displacing = C.int(0);
    let i, nx, ny;
    let ndist;

    for (i = C.int(0); i < data.cnt; i++) {
        nx = C.int(data.poss[i].x);
        ny = C.int(data.poss[i].y);
        ndist = C.int(C.dist2(nx, ny, ggx, ggy));
        if (C.bool(C.bool(C.bool(C.MON_AT(nx, ny) && (data.info[i] & C.ALLOW_MDISP)) && !(data.info[i] & C.ALLOW_M))
            && !undesirable_disp(mtmp, nx, ny))) {
            if (C.bool(shortest_with_displacing == -1
                || (ndist < shortest_with_displacing)))
                shortest_with_displacing = C.int(ndist);
        } else {
            if (C.bool((shortest_without_displacing == -1)
                || (ndist < shortest_without_displacing)))
                shortest_without_displacing = C.int(ndist);
            count_without_displacing++;
        }
    }
    if (C.bool(shortest_with_displacing > -1
        && (C.bool(shortest_with_displacing < shortest_without_displacing
            || !count_without_displacing))))
        return 1;
    return 0;
}

/* have monster wield a pick-axe if it wants to dig and it has one;
   return True if it spends this move wielding one, False otherwise */
function m_digweapon_check(mtmp, nix, niy)

{
    nix = C.coordxy(C.coordxy(nix)); niy = C.coordxy(C.coordxy(niy));
    let can_tunnel = C.char(0);
    let mw_tmp = C.MON_WEP(mtmp);

    if (!C.Is_rogue_level(C.u.uz))
        can_tunnel = C.char(C.tunnels(mtmp.data));

    if (C.bool(C.bool(C.bool(can_tunnel && C.needspick(mtmp.data)) && !C.mwelded(mw_tmp))
        && (C.bool(C.may_dig(nix, niy) || closed_door(nix, niy))))) {
        /* may_dig() is either IS_STWALL or IS_TREE */
        if (closed_door(nix, niy)) {
            if (C.bool(C.bool(!mw_tmp || !C.is_pick(mw_tmp)) || !C.is_axe(mw_tmp)))
                mtmp.weapon_check = C.NEED_PICK_OR_AXE;
        } else if (C.IS_TREE(C.levl[nix][niy].typ)) {
            if (C.bool(!mw_tmp || !C.is_axe(mw_tmp)))
                mtmp.weapon_check = C.NEED_AXE;
        } else if (C.IS_STWALL(C.levl[nix][niy].typ)) {
            if (C.bool(!mw_tmp || !C.is_pick(mw_tmp)))
                mtmp.weapon_check = C.NEED_PICK_AXE;
        }
        if (C.bool(mtmp.weapon_check >= C.NEED_PICK_AXE && C.mon_wield_item(mtmp)))
            return 1;
    }
    return 0;
}

/* does leprechaun want to avoid the hero? */
function leppie_avoidance(mtmp)

{
    let lepgold, ygold;

    if (C.bool(C.samePtr(mtmp.data, C.mons[C.PM_LEPRECHAUN])
        && (C.bool((lepgold = C.findgold(mtmp.minvent))
            && (lepgold.quan
                > ((ygold = C.findgold(C.gi.invent)) ? ygold.quan : 0n))))))
        return 1;

    return 0;
}

/* unseen leprechaun with gold might stash it */
function leppie_stash(mtmp)

{
    let gold;

    if (C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.samePtr(mtmp.data, C.mons[C.PM_LEPRECHAUN])
        && !C.DEADMONSTER(mtmp))
        && !C.m_canseeu(mtmp))
        && !C.loadChar(C.in_rooms(mtmp.mx, mtmp.my, C.SHOPBASE)))
        && C.levl[mtmp.mx][mtmp.my].typ == C.ROOM)
        && !C.t_at(mtmp.mx, mtmp.my))
        && C.rn2(4, 1164, "leppie_stash"))
        && (gold = C.findgold(mtmp.minvent)) != 0)) {
        C.mdrop_obj(mtmp, gold, 0);
        gold = C.g_at(mtmp.mx, mtmp.my);
        if (gold)
            C.bury_an_obj(gold, 0);
    }
}

/* does monster want to avoid you?
 *  returns the original value of appr if not.
 *  returns -1 if so.
 *  returns -2 if monster wants to adhere to a particular range,
 *             which may actually be further away,
 *             and sets *pdistmin and *pdistmax to describe that range
 */
function m_balks_at_approaching(oldappr, mtmp, pdistmin, pdistmax)

{
    oldappr = C.int(C.int(oldappr));
    let mwep = C.MON_WEP(mtmp);
    let x = C.coordxy(mtmp.mx), y = C.coordxy(mtmp.my), ux = C.coordxy(mtmp.mux), uy = C.coordxy(mtmp.muy);
    let edist = C.int(C.dist2(x, y, ux, uy));
    let arw;

    if (pdistmin)
        pdistmin.value = 0;
    if (pdistmax)
        pdistmax.value = 0;

    /* peaceful, far away, or can't see you */
    if (C.bool(C.bool(mtmp.mpeaceful || (edist >= 5 * 5)) || !C.m_canseeu(mtmp)))
        return oldappr;

    /* has ammo+launcher */
    if (C.m_has_launcher_and_ammo(mtmp))
        return -1;

    /* is using a polearm and in range */
    if (C.bool(C.bool(C.MON_WEP(mtmp) && C.is_pole(C.MON_WEP(mtmp)))
        && edist <= C.MON_POLE_DIST))
        return -1;

    /* is using a throw-and-return weapon; provide min and max preferred range
     */
    if (C.bool(mwep && (arw = C.autoreturn_weapon(mwep)) != 0)) {
        if (pdistmin)
            pdistmin.value = 2 * 2;
        if (pdistmax)
            pdistmax.value = arw.range;
        return -2;
    }

    /* can attack from distance, and hp loss or attack not used */
    if (C.bool(C.ranged_attk_available(mtmp)
        && (C.bool((mtmp.mhp < C.intdiv(mtmp.mhpmax+1, 3))
            || !mtmp.mspec_used))))
        return -1;

    return oldappr; /* leaves appr unchanged */
}

function holds_up_web(x, y)

{
    x = C.coordxy(C.coordxy(x)); y = C.coordxy(C.coordxy(y));
    let sway;

    if (C.bool(C.bool(C.bool(!C.isok(x, y)
        || C.IS_OBSTRUCTED(C.levl[x][y].typ))
        || (C.bool(C.bool((C.bool(C.levl[x][y].typ == C.STAIRS || C.levl[x][y].typ == C.LADDER))
            && (sway = C.stairway_at(x, y)) != 0) && sway.up)))
        || C.levl[x][y].typ == C.IRONBARS))
        return 1;

    return 0;
}

/* returns the number of walls in the four cardinal directions that could
   hold up a web */
function count_webbing_walls(x, y)

{
    x = C.coordxy(C.coordxy(x)); y = C.coordxy(C.coordxy(y));
    return (holds_up_web(x, y - 1) + holds_up_web(x + 1, y)
            + holds_up_web(x, y + 1) + holds_up_web(x - 1, y));
}

/* reject webs which interfere with solving Sokoban */
function soko_allow_web(mon)

{
    let stway;

    /* for a non-Sokoban level or a solved Sokoban level, no restriction */
    if (!C.Sokoban)
        return 1;
    /* not-yet-solved Sokoban level:  allow web only when spinner can see
       the stairs up [we really want 'is in same chamber as stairs up'] */
    stway = C.stairway_find_dir(1); /* stairs up */
    if (C.bool(stway && C.m_cansee(mon, stway.sx, stway.sy)))
        return 1;
    return 0;
}

/* monster might spin a web */
function maybe_spin_web(mtmp)

{
    if (C.bool(C.bool(C.bool(C.bool(C.webmaker(mtmp.data)
        && !C.helpless(mtmp)) && !mtmp.mspec_used)
        && !C.t_at(mtmp.mx, mtmp.my)) && soko_allow_web(mtmp))) {
        let trap;
        let prob = (C.int((((C.samePtr(mtmp.data, C.mons[C.PM_GIANT_SPIDER])) ? 15 : 5)
                     * (count_webbing_walls(mtmp.mx, mtmp.my) + 1))
                    - (3 * C.count_traps(C.WEB))));

        if (C.bool(C.rn2(1000, 1279, "maybe_spin_web") < prob
            && (trap = C.maketrap(mtmp.mx, mtmp.my, C.WEB)) != 0)) {
            mtmp.mspec_used = C.d(4, 4, 1281, "maybe_spin_web"); /* 4..16 */
            if (C.cansee(mtmp.mx, mtmp.my)) {
                const mbuf = C.stackAlloc(C.BUFSZ);

                C.Strcpy(mbuf, C.canspotmon(mtmp) ? C.y_monnam(mtmp) : C.something);
                C.pline_mon(mtmp, "%s spins a web.", C.upstart(mbuf));
                trap.tseen = 1;
            }
            if (C.loadChar(C.in_rooms(mtmp.mx, mtmp.my, C.SHOPBASE)))
                C.add_damage(mtmp.mx, mtmp.my, 0n);
        }
    }
}

/* monster avoids a location nx, ny, if hero kicked that location */
function m_avoid_kicked_loc(mtmp, nx, ny)

{
    nx = C.coordxy(C.coordxy(nx)); ny = C.coordxy(C.coordxy(ny));
    if (C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool((C.bool(mtmp.mpeaceful || mtmp.mtame))
        && mtmp.mcansee)
        && !mtmp.mconf) && !mtmp.mstun)
        && !C.Conflict)
        && C.isok(C.gk.kickedloc.x, C.gk.kickedloc.y))
        && nx == C.gk.kickedloc.x) && ny == C.gk.kickedloc.y)
        && C.next2u(nx, ny)))
        return 1;
    return 0;
}

/* monster avoids a location nx, ny, if we're in sokoban, and
   there's a boulder between the location and hero */
function m_avoid_soko_push_loc(mtmp, nx, ny)

{
    nx = C.coordxy(C.coordxy(nx)); ny = C.coordxy(C.coordxy(ny));
    if (C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.Sokoban
        && (C.bool(mtmp.mpeaceful || mtmp.mtame)))
        && !mtmp.mconf) && !mtmp.mstun)
        && !C.Conflict)
        && (C.dist2(nx, ny, C.u.ux, C.u.uy) == 4))
        && C.sobj_at(C.BOULDER, nx + C.sgn(C.u.ux - nx), ny + C.sgn(C.u.uy - ny))))
        return 1;
    return 0;
}

/* max distmin() distance for monster to look for items */

/* monster looks for items it wants nearby */
const SQSRCHRADIUS=5;

function m_search_items(mtmp, ggx, ggy, mmoved, appr)

{
    let minr = C.int(SQSRCHRADIUS); /* not too far away */
    let otmp;
    let xx, yy;
    let hmx, hmy, lmx, lmy;
    let ttmp;
    let omx = C.coordxy(mtmp.mx), omy = C.coordxy(mtmp.my);
    let ptr = mtmp.data;
    let mtoo;
    let costly;

    /* cut down the search radius if it thinks character is closer. */
    if (C.bool(C.distmin(mtmp.mux, mtmp.muy, omx, omy) < SQSRCHRADIUS
        && !mtmp.mpeaceful))
        minr--;
    /* guards shouldn't get too distracted */
    if (C.bool(!mtmp.mpeaceful && C.is_mercenary(ptr)))
        minr = C.int(1);

    /* in shop, usually skip */
    finish_search: {
    if (C.bool(C.loadChar(C.in_rooms(omx, omy, C.SHOPBASE)) && (C.bool(C.rn2(25, 1355, "m_search_items") || mtmp.isshk))))
        break finish_search;

    /* distmin() gives a rectangular area */
    hmx = C.coordxy(C.min(C.COLNO - 1, omx + minr));
    hmy = C.coordxy(C.min(C.ROWNO - 1, omy + minr));
    lmx = C.coordxy(C.max(1, omx - minr));
    lmy = C.coordxy(C.max(0, omy - minr));

    for (xx = C.coordxy(lmx); xx <= hmx; xx++) {
        for (yy = C.coordxy(lmy); yy <= hmy; yy++) {
            /* no object here */
            if (!C.OBJ_AT(xx, yy))
                continue;
            /* found an object closer already */
            if (minr < C.distmin(omx, omy, xx, yy))
                continue;
            /* the mfndpos() test for whether to allow a move to a
               water location accepts flyers, but they can't reach
               underwater objects, so being able to move to a spot
               is insufficient for deciding whether to do so */
            if (!C.could_reach_item(mtmp, xx, yy))
                continue;
            /* hiders avoid hero's line of sight */
            if (C.bool(C.hides_under(ptr) && C.cansee(xx, yy)))
                continue;
            /* don't get stuck circling around object that's
               underneath an immobile or hidden monster;
               paralysis victims excluded */
            if (C.bool((mtoo = C.m_at(xx, yy)) != 0
                && (C.bool(C.bool(C.bool(C.helpless(mtoo) || mtoo.mundetected)
                    || (C.bool(mtoo.mappearance && !mtoo.iswiz)))
                    || !mtoo.data.mmove))))
                continue;
            /* Don't get stuck circling an Elbereth */
            if (onscary(xx, yy, mtmp))
                continue;
            /* ignore obj if there's a trap and monster knows it */
            if (C.bool((ttmp = C.t_at(xx, yy)) != 0
                && C.mon_knows_traps(mtmp, ttmp.ttyp))) {
                if (C.bool(ggx.value == xx && ggy.value == yy)) {
                    ggx.value = mtmp.mux;
                    ggy.value = mtmp.muy;
                }
                continue;
            }
            /* avoid getting stuck on eg. items in niches */
            if (!C.m_cansee(mtmp, xx, yy))
                continue;

            costly = C.char(C.costly_spot(xx, yy));

            /* look through the items on this location */
            for (otmp = C.svl.level.objects[xx][yy];
                 otmp; otmp = otmp.nexthere) {
                /* monsters may pick rocks up, but won't go out of their way
                   to grab them; this might hamper sling wielders, but it cuts
                   down on move overhead by filtering out most common item */
                if (otmp.otyp == C.ROCK)
                    continue;
                /* avoid special items; once hero picks them up, they'll
                   cease being special */
                if (C.bool(C.is_mines_prize(otmp) || C.is_soko_prize(otmp)))
                    continue;
                /* skip shop merchandise */
                if (C.bool(costly && !otmp.no_charge))
                    continue;

                if (C.bool((C.bool((C.bool(mon_would_take_item(mtmp, otmp)
                      && (C.can_carry(mtmp, otmp) > 0)))
                     || mon_would_consume_item(mtmp, otmp)))
                    && C.can_touch_safely(mtmp, otmp))) {
                    minr = C.int(C.distmin(omx, omy, xx, yy));
                    ggx.value = otmp.ox;
                    ggy.value = otmp.oy;
                    if (C.bool(ggx.value == omx && ggy.value == omy)) {
                        mmoved.value = C.MMOVE_DONE; /* actually unnecessary */
                        return 1;
                    }
                    /* found an item of interest; skip the rest of the pile */
                    break;
                }
            }
        }
    }

    }
    if (C.bool(minr < SQSRCHRADIUS && appr.value == -1)) {
        if (C.distmin(omx, omy, mtmp.mux, mtmp.muy) <= 3) {
            ggx.value = mtmp.mux;
            ggy.value = mtmp.muy;
        } else
            appr.value = 1;
    }
    return 0;
}


function postmov(mtmp, ptr, omx, omy, mmoved, seenflgs, can_tunnel, can_unlock, can_open)

{
    omx = C.coordxy(C.coordxy(omx)); omy = C.coordxy(C.coordxy(omy)); mmoved = C.int(C.int(mmoved)); seenflgs = C.uint(C.uint(seenflgs)); can_tunnel = C.char(C.boolean(can_tunnel)); can_unlock = C.char(C.boolean(can_unlock)); can_open = C.char(C.boolean(can_open));
    let nix, niy;
    let etmp, trapret;
    let canseeit = C.char(C.cansee(mtmp.mx, mtmp.my)),
            didseeit = C.char(canseeit);

    C.notice_mon(mtmp);

    if (mmoved == C.MMOVE_MOVED) {
        nix = C.coordxy(mtmp.mx), niy = C.coordxy(mtmp.my);
        /* sequencing issue:  when monster movement decides that a
           monster can move to a door location, it moves the monster
           there before dealing with the door rather than after;
           so a vampire/bat that is going to shift to fog cloud and
           pass under the door is already there but transformation
           into fog form--and its message, when in sight--has not
           happened yet; we have to move monster back to previous
           location before performing the vamp_shift() to make the
           message happen at right time, then back to the door again
           [if we did the shift sooner, before moving the monster,
           we would need to duplicate it in dog_move()...] */
        if (C.bool(C.bool(C.bool(C.bool(C.is_vampshifter(mtmp) && !C.amorphous(mtmp.data))
            && C.IS_DOOR(C.levl[nix][niy].typ))
            && ((C.levl[nix][niy].doormask & (C.D_LOCKED | C.D_CLOSED)) != 0))
            && can_fog(mtmp))) {
            /* note: remove_monster()+place_monster is not right for
               long worms but they won't reach here */
            if (seenflgs) {
                C.remove_monster(nix, niy);
                C.place_monster(mtmp, omx, omy);
                C.newsym(nix, niy), C.newsym(omx, omy);
            }
            if (vamp_shift(mtmp, C.mons[C.PM_FOG_CLOUD],
                           ((seenflgs & 1) != 0) ? 1 : 0)) {
                ptr = mtmp.data; /* update cached value */
                C.nhUse(ptr);
            }
            if (seenflgs) {
                C.remove_monster(omx, omy);
                C.place_monster(mtmp, nix, niy);
                C.newsym(omx, omy), C.newsym(nix, niy);
            }
        }

        C.newsym(omx, omy); /* update the old position */
        trapret = C.int(C.mintrap(mtmp, C.NO_TRAP_FLAGS));
        if (C.bool(trapret == C.Trap_Killed_Mon || trapret == C.Trap_Moved_Mon)) {
            if (mtmp.mx)
                C.newsym(mtmp.mx, mtmp.my);
            return C.MMOVE_DIED; /* it died */
        } else if (C.mon_offmap(mtmp)) {
            return C.MMOVE_DONE;
        }
        ptr = mtmp.data; /* in case mintrap() caused polymorph */

        /* open a door, or crash through it, if 'mtmp' can */
        if (C.bool(C.bool(C.IS_DOOR(C.levl[mtmp.mx][mtmp.my].typ)
            && !C.passes_walls(ptr)) /* doesn't need to open doors */
            && !can_tunnel)) {     /* taken care of below */
            let here = C.levl[mtmp.mx][mtmp.my];
            let btrapped = C.char((here.doormask & C.D_TRAPPED) != 0);

    /* used after monster 'who' has been moved to closed door spot 'where'
       which will now be changed to door state 'what' with map update */



            /* if mon has MKoT, disarm door trap; no message given */
            if (C.bool(btrapped && C.has_magic_key(mtmp))) {
                /* BUG: this lets a vampire or blob or a doorbuster
                   holding the Key disarm the trap even though it isn't
                   using that Key when squeezing under or smashing the
                   door.  Not significant enough to worry about; perhaps
                   the Key's magic is more powerful for monsters? */
                here.doormask &= ~C.D_TRAPPED;
                btrapped = C.char(0);
            }
            if (C.bool((here.doormask & (C.D_LOCKED | C.D_CLOSED)) != 0
                && C.amorphous(ptr))) {
                if (C.bool(C.flags.verbose && C.canseemon(mtmp)))
                    C.pline_mon(mtmp, "%s %s under the door.", C.YMonnam(mtmp),
                              (C.bool(C.samePtr(ptr, C.mons[C.PM_FOG_CLOUD])
                               || ptr.mlet == C.S_LIGHT)) ? "flows" : "oozes");
            } else if (C.bool((here.doormask & C.D_LOCKED) != 0 && can_unlock)) {
                /* like the vampshift hack, there are sequencing
                   issues when the monster is moved to the door's spot
                   first then door handling plus feedback comes after */

                here.doormask = !btrapped ? C.D_ISOPEN : C.D_NODOOR;
                C.newsym(mtmp.mx, mtmp.my);
                C.recalc_block_point(mtmp.mx, mtmp.my);
                C.vision_recalc(0);
                canseeit = C.char(C.bool(didseeit || C.cansee(mtmp.mx, mtmp.my)));
                if (btrapped) {
                    if (mb_trapped(mtmp, canseeit))
                        return C.MMOVE_DIED;
                } else {
                    
                    if (C.flags.verbose) {
                        if (C.bool(canseeit && C.canspotmon(mtmp))) {
                            C.pline_mon(mtmp, "%s unlocks and opens a door.",
                                  C.Monnam(mtmp));
                        } else if (canseeit) {
                            C.You_see("a door unlock and open.");
                        } else if (!C.Deaf) {
                            C.You_hear("a door unlock and open.");
                        }
                    }
                }
            } else if (C.bool(here.doormask == C.D_CLOSED && can_open)) {
                here.doormask = !btrapped ? C.D_ISOPEN : C.D_NODOOR;
                C.newsym(mtmp.mx, mtmp.my);
                C.recalc_block_point(mtmp.mx, mtmp.my);
                C.vision_recalc(0);
                canseeit = C.char(C.bool(didseeit || C.cansee(mtmp.mx, mtmp.my)));
                if (btrapped) {
                    if (mb_trapped(mtmp, canseeit))
                        return C.MMOVE_DIED;
                } else {
                    
                    if (C.flags.verbose) {
                        if (C.bool(canseeit && C.canspotmon(mtmp))) {
                            C.pline_mon(mtmp, "%s opens a door.", C.Monnam(mtmp));
                        } else if (canseeit) {
                            C.You_see("a door open.");
                        } else if (!C.Deaf) {
                            C.You_hear("a door open.");
                        }
                    }
                }
            } else if ((here.doormask & (C.D_LOCKED | C.D_CLOSED)) != 0) {
                /* mfndpos guarantees this must be a doorbuster */
                let mask;

                mask = C.uint((C.bool(btrapped
                         || (C.bool((here.doormask & C.D_LOCKED) != 0 && !C.rn2(2, 1598, "postmov")))))
                        ? C.D_NODOOR
                        : C.D_BROKEN);
                here.doormask = mask;
                C.newsym(mtmp.mx, mtmp.my);
                C.recalc_block_point(mtmp.mx, mtmp.my);
                C.vision_recalc(0);
                canseeit = C.char(C.bool(didseeit || C.cansee(mtmp.mx, mtmp.my)));
                if (btrapped) {
                    if (mb_trapped(mtmp, canseeit))
                        return C.MMOVE_DIED;
                } else {
                    
                    if (C.flags.verbose) {
                        if (C.bool(canseeit && C.canspotmon(mtmp))) {
                            C.pline_mon(mtmp, "%s smashes down a door.",
                                      C.Monnam(mtmp));
                        } else if (canseeit) {
                            C.You_see("a door crash open.");
                        } else if (!C.Deaf) {
                            C.You_hear("a door crash open.");
                        }
                    }
                }
                /* if it's a shop door, schedule repair */
                if (C.loadChar(C.in_rooms(mtmp.mx, mtmp.my, C.SHOPBASE)))
                    C.add_damage(mtmp.mx, mtmp.my, 0n);
            }

        } else if (C.levl[mtmp.mx][mtmp.my].typ == C.IRONBARS) {
            /* 3.6.2: was using may_dig() but that doesn't handle bars;
               AD_RUST catches rust monsters but metallivorous() is
                   needed for xorns and rock moles */
            if (C.bool(!(C.levl[mtmp.mx][mtmp.my].wall_info & C.W_NONDIGGABLE)
                && (C.bool(C.bool(C.dmgtype(ptr, C.AD_RUST) || C.dmgtype(ptr, C.AD_CORR))
                    || C.metallivorous(ptr))))) {
                if (C.canseemon(mtmp))
                    C.pline_mon(mtmp, "%s eats through the iron bars.",
                              C.Monnam(mtmp));
                dissolve_bars(mtmp.mx, mtmp.my);
                return C.MMOVE_DONE;
            } else if (C.bool(C.flags.verbose && C.canseemon(mtmp)))
                C.Norep("%s %s %s the iron bars.", C.Monnam(mtmp),
                      /* pluralization fakes verb conjugation */
                      C.makeplural(C.locomotion(ptr, "pass")),
                      C.passes_walls(ptr) ? "through" : "between");
        } /* doors and bars */

        /* possibly dig */
        if (C.bool(C.bool(can_tunnel && C.may_dig(mtmp.mx, mtmp.my))
            && C.mdig_tunnel(mtmp)))
            return C.MMOVE_DIED; /* mon died (position already updated) */

        /* set also in domove(), hack.c */
        if (C.bool(C.engulfing_u(mtmp) && (C.bool(mtmp.mx != omx || mtmp.my != omy)))) {
            /* If the monster moved, then update */
            C.u.ux0 = C.u.ux;
            C.u.uy0 = C.u.uy;
            C.u_on_newpos(mtmp.mx, mtmp.my);
            C.swallowed(0);
        } else {
            C.newsym(mtmp.mx, mtmp.my);
        }
    } /* mmoved==MMOVE_MOVED */

    if (C.bool(mmoved == C.MMOVE_MOVED || mmoved == C.MMOVE_DONE)) {
        if (C.bool(C.OBJ_AT(mtmp.mx, mtmp.my) && mtmp.mcanmove)) {

            /* Maybe a rock mole just ate some metal object */
            if (C.metallivorous(ptr)) {
                if (C.meatmetal(mtmp) == 2)
                    return C.MMOVE_DIED; /* it died */
            }

            /* Maybe a cube ate just about anything */
            if (C.samePtr(ptr, C.mons[C.PM_GELATINOUS_CUBE])) {
                if ((etmp = C.int(C.meatobj(mtmp))) >= 2)
                    return etmp; /* it died or got forced off the level */
            }
            /* Maybe a purple worm ate a corpse */
            if (C.corpse_eater(ptr)) {
                if ((etmp = C.int(C.meatcorpse(mtmp))) >= 2)
                    return etmp; /* it died or got forced off the level */
            }

            if (C.mpickstuff(mtmp))
                mmoved = C.int(C.MMOVE_DONE);

            if (mtmp.minvis) {
                C.newsym(mtmp.mx, mtmp.my);
                if (mtmp.wormno)
                    C.see_wsegs(mtmp);
            }
        }

        maybe_spin_web(mtmp);

        if (C.bool(C.hides_under(ptr) || ptr.mlet == C.S_EEL)) {
            /* Always set--or reset--mundetected if it's already hidden
               (just in case the object it was hiding under went away);
               usually set mundetected unless monster can't move. */
            if (C.bool(mtmp.mundetected || (C.bool(!C.helpless(mtmp) && C.rn2(5, 1696, "postmov")))))
                C.hideunder(mtmp);
            C.newsym(mtmp.mx, mtmp.my);
        }
        if (mtmp.isshk) {
            C.after_shk_move(mtmp);
        }
    }
    return mmoved;
}

/* Handles the movement of a standard monster.
 * Return values:
 * 0: did not move, but can still attack and do other stuff;
 * 1: moved, possibly can attack;
 * 2: monster died;
 * 3: did not move, and can't do anything else either.
 */
function m_move(mtmp, after)

{
    after = C.int(C.int(after));
    const appr=C.intLocal();
    const ggx=C.coordxyLocal(), ggy=C.coordxyLocal(); let nix, niy;
    let chcnt;
    let can_tunnel = C.char(0);
    let can_open = C.char(0), can_unlock = C.char(0) /*, doorbuster = 0 */;
    let getitems = C.char(0);
    let avoid = C.char(0);
    let better_with_displacing = C.char(0);
    let seenflgs;
    let ptr;
    let chi; const mmoved=C.intLocal(C.MMOVE_NOTHING); let /* not strictly nec.: chi >= 0 will do */
        preferredrange_min=C.intLocal(0), preferredrange_max=C.intLocal(0);
    const mfp = C.mfndposLocal();
    let flag;
    let omx = C.coordxy(mtmp.mx), omy = C.coordxy(mtmp.my);

    if (mtmp.mtrapped) {
        let i = C.int(C.mintrap(mtmp, C.NO_TRAP_FLAGS));

        if (i == C.Trap_Killed_Mon) {
            C.newsym(mtmp.mx, mtmp.my);
            return C.MMOVE_DIED;
        } /* it died */
        if (i == C.Trap_Caught_Mon)
            return C.MMOVE_NOTHING; /* still in trap, so didn't move */
    }
    ptr = mtmp.data; /* mintrap() can change mtmp->data -dlc */

    if (mtmp.meating) {
        mtmp.meating--;
        if (mtmp.meating <= 0)
            C.finish_meating(mtmp);
        return C.MMOVE_DONE; /* still eating */
    }
    if (C.bool(C.bool(C.bool(C.hides_under(ptr) && C.OBJ_AT(mtmp.mx, mtmp.my))
        && can_hide_under_obj(C.svl.level.objects[mtmp.mx][mtmp.my]))
        && C.rn2(10, 1753, "m_move")))
        return C.MMOVE_NOTHING; /* do not leave hiding place */

    /* set up pre-move visibility flags */
    seenflgs = C.uint((C.canseemon(mtmp) ? 1 : 0) | (C.canspotmon(mtmp) ? 2 : 0));

    /* Where does 'mtmp' think you are?  Not necessary if m_move() called
       from this file, but needed for other calls of m_move(). */
    set_apparxy(mtmp); /* set mtmp->mux, mtmp->muy */

    if (!C.Is_rogue_level(C.u.uz))
        can_tunnel = C.char(C.tunnels(ptr));
    can_open = C.char(!(C.bool(C.nohands(ptr) || C.verysmall(ptr))));
    can_unlock = C.char(C.bool(C.bool((C.bool(can_open && monhaskey(mtmp, 1)))
                  || mtmp.iswiz) || C.is_rider(ptr)));
    /* doorbuster = is_giant(ptr); */
    not_special: {
    if (mtmp.wormno)
        break not_special;
    /* my dog gets special treatment */
    if (mtmp.mtame) {
        return postmov(mtmp, ptr, omx, omy, C.dog_move(mtmp, after),
                       seenflgs, can_tunnel, can_unlock, can_open);
    }

    /* and the acquisitive monsters get special treatment */
    if (C.is_covetous(ptr)) { /* [should this include
                             *  '&& mtmp->mstrategy != STRAT_NONE'?] */
        let covetousattack;
        let tx = C.coordxy(mtmp.mgoal.x),
                ty = C.coordxy(mtmp.mgoal.y);
        let intruder = C.isok(tx, ty) ? C.m_at(tx, ty) : 0;
        /*
         * if there's a monster on the object or in possession of it,
         * attack it.
         */
        if (C.bool(C.bool(intruder && !C.samePtr(intruder, mtmp))
            /* 5.0: this used to use 'dist2() < 2' which meant that intended
               attack was disallowed if they were adjacent diagonally */
            && C.dist2(mtmp.mx, mtmp.my, tx, ty) <= 2)) {
            C.gb.bhitpos.x = tx, C.gb.bhitpos.y = ty;
            C.gn.notonhead = (C.bool(intruder.mx != tx || intruder.my != ty));
            covetousattack = C.int(C.mattackm(mtmp, intruder));
            /* 5.0: this used to erroneously use '== 2' (M_ATTK_DEF_DIED) */
            if (covetousattack & C.M_ATTK_AGR_DIED)
                return C.MMOVE_DIED;
            mmoved.value = C.MMOVE_MOVED;
            return postmov(mtmp, ptr, omx, omy, mmoved.value,
                           seenflgs, can_tunnel, can_unlock, can_open);
        }
        /* otherwise continue with normal AI routine */
    }

    /* likewise for shopkeeper, guard, or priest */
    if (C.bool(C.bool(mtmp.isshk || mtmp.isgd) || mtmp.ispriest)) {
        let xm = C.int(mtmp.isshk ? C.shk_move(mtmp)
                 : mtmp.isgd ? C.gd_move(mtmp)
                   : C.pri_move(mtmp));

        switch (xm) {
        case -2:
            return C.MMOVE_DIED;
        case -1:
            mmoved.value = C.MMOVE_NOTHING; /* shk follow hero outside shop */
            break;
        default:
            C.impossible("unknown shk/gd/pri_move return value (%d)", xm);
            
            /*FALLTHRU*/
        case 0:
        case 1:
            return postmov(mtmp, ptr, omx, omy,
                           (xm != 1) ? C.MMOVE_NOTHING : C.MMOVE_MOVED,
                           seenflgs, can_tunnel, can_unlock, can_open);
        }
    }




    if (C.samePtr(ptr, C.mons[C.PM_MAIL_DAEMON])) {
        if (C.bool(!C.Deaf && C.canseemon(mtmp))) {
            C.verbalize("I'm late!");
        }
        C.mongone(mtmp);
        return C.MMOVE_DIED;
    }

    /* teleport if that lies in our nature */
    if (C.bool(C.bool(C.bool(C.samePtr(ptr, C.mons[C.PM_TENGU]) && !C.rn2(5, 1841, "m_move")) && !mtmp.mcan)
        && !C.tele_restrict(mtmp))) {
        if (C.bool(C.bool(mtmp.mhp < 7 || mtmp.mpeaceful) || C.rn2(2, 1843, "m_move")))
            C.rloc(mtmp, C.RLOC_MSG);
        else
            C.mnexto(mtmp, C.RLOC_MSG);
        return postmov(mtmp, ptr, omx, omy, C.MMOVE_MOVED,
                       seenflgs, can_tunnel, can_unlock, can_open);
    }
    }
    if (C.bool(C.bool(C.u.uswallow && !mtmp.mflee) && !C.samePtr(C.u.ustuck, mtmp)))
        return C.MMOVE_MOVED;
    omx = C.coordxy(mtmp.mx);
    omy = C.coordxy(mtmp.my);
    ggx.value = mtmp.mux;
    ggy.value = mtmp.muy;
    appr.value = mtmp.mflee ? -1 : 1;
    if (C.bool(mtmp.mconf || C.engulfing_u(mtmp))) {
        appr.value = 0;
    } else {
        let should_see = (C.char(C.bool(C.bool(C.couldsee(omx, omy)
                              && (C.bool(C.levl[ggx.value][ggy.value].lit || !C.levl[omx][omy].lit)))
                              && (C.dist2(omx, omy, ggx.value, ggy.value) <= 36))));

        if (C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(!mtmp.mcansee
            || (C.bool(C.bool(C.bool(should_see && C.Invis) && !C.perceives(ptr)) && C.rn2(11, 1866, "m_move"))))
            || C.is_obj_mappear(C.gy.youmonst, C.STRANGE_OBJECT)) || C.u.uundetected)
            || (C.bool(C.is_obj_mappear(C.gy.youmonst, C.GOLD_PIECE) && !C.likes_gold(ptr))))
            || (C.bool(mtmp.mpeaceful && !mtmp.isshk))) /* allow shks to follow */
            || (C.bool((C.bool(C.bool(C.monsndx(ptr) == C.PM_STALKER || ptr.mlet == C.S_BAT)
                 || ptr.mlet == C.S_LIGHT)) && !C.rn2(3, 1871, "m_move")))))
            appr.value = 0;

        if (C.bool(appr.value == 1 && leppie_avoidance(mtmp)))
            appr.value = -1;

        /* hostiles with ranged weapon or attack try to stay away */
        appr.value = m_balks_at_approaching(appr.value, mtmp, preferredrange_min, preferredrange_max);

        if (C.bool(!should_see && C.can_track(ptr))) {
            let cp;

            cp = C.gettrack(omx, omy);
            if (cp) {
                ggx.value = cp.x;
                ggy.value = cp.y;
            }
        }
    }

    if (C.bool((C.bool(!mtmp.mpeaceful || !C.rn2(10, 1891, "m_move"))) && (!C.Is_rogue_level(C.u.uz)))) {
        let in_line = (C.char(C.bool(C.lined_up(mtmp)
             && (C.distmin(mtmp.mx, mtmp.my, mtmp.mux, mtmp.muy)
                 <= (C.throws_rocks(C.gy.youmonst.data) ? 20
                                                    : (C.intdiv(C.ACURRSTR, 2) + 1))))));

        if (C.bool(appr.value != 1 || !in_line)) {
            /* Monsters in combat won't pick stuff up, avoiding the
             * situation where you toss arrows at it and it has nothing
             * better to do than pick the arrows up.
             */
            getitems = C.char(1);
        }
    }

    if (C.bool(getitems && m_search_items(mtmp, ggx, ggy, mmoved, appr)))
        return postmov(mtmp, ptr, omx, omy, mmoved.value,
                       seenflgs, can_tunnel, can_unlock, can_open);

    /* don't tunnel if hostile and close enough to prefer a weapon */
    if (C.bool(C.bool(can_tunnel && C.needspick(ptr))
        && (C.bool((C.bool(!mtmp.mpeaceful || C.Conflict))
            && C.dist2(mtmp.mx, mtmp.my, mtmp.mux, mtmp.muy) <= 8))))
        can_tunnel = C.char(0);

    nix = C.coordxy(omx);
    niy = C.coordxy(omy);
    flag = C.long(C.mon_allowflags(mtmp));
    {
        let i, j, nx, ny, nearer;
        let jcnt, cnt;
        let ndist, nidist;
        let mtrk;

        cnt = C.int(C.mfndpos(mtmp, mfp, flag));
        if (C.bool(cnt == 0 && !C.is_unicorn(mtmp.data))) {
            if (C.bool(C.find_defensive(mtmp, 1) && C.use_defensive(mtmp)))
                return C.MMOVE_DONE;
            return C.MMOVE_NOMOVES;
        }
        chcnt = C.coordxy(0);
        jcnt = C.int(C.min(C.MTSZ, cnt - 1));
        chi = C.int(-1);
        nidist = C.int(C.dist2(nix, niy, ggx.value, ggy.value));
        /* allow monsters be shortsighted on some levels for balance */
        if (C.bool(C.bool(C.bool(!mtmp.mpeaceful && C.svl.level.flags.shortsighted)
            && nidist > (C.couldsee(nix, niy) ? 144 : 36)) && appr.value == 1))
            appr.value = 0;
        if (C.bool(C.is_unicorn(ptr) && C.noteleport_level(mtmp))) {
            /* on noteleport levels, perhaps we cannot avoid hero */
            for (i = C.int(0); i < cnt; i++)
                if (!(mfp.info[i] & C.NOTONL))
                    avoid = C.char(1);
        }
        better_with_displacing = C.char(should_displace(mtmp, mfp, ggx.value, ggy.value));
        nxti: for (i = C.int(0); i < cnt; i++) {
            if (C.bool(avoid && (mfp.info[i] & C.NOTONL)))
                continue;
            nx = C.int(mfp.poss[i].x);
            ny = C.int(mfp.poss[i].y);

            if (m_avoid_kicked_loc(mtmp, nx, ny))
                continue;

            if (C.bool(C.bool(C.bool(C.MON_AT(nx, ny) && (mfp.info[i] & C.ALLOW_MDISP))
                && !(mfp.info[i] & C.ALLOW_M)) && !better_with_displacing))
                continue;
            if (appr.value != 0) {
                mtrk = mtmp.mtrack[0];
                for (j = C.int(0); j < jcnt; j++)
                    if (C.bool(nx == mtmp.mtrack[j].x && ny == mtmp.mtrack[j].y))
                        if (C.rn2(4 * (cnt - j), 1963, "m_move"))
                            continue nxti;
            }

            nearer = C.int((ndist = C.int(C.dist2(nx, ny, ggx.value, ggy.value))) < nidist);

            if (C.bool(C.bool(C.bool(C.bool((C.bool(appr.value == 1 && nearer)) || (C.bool(appr.value == -1 && !nearer)))
                || (C.bool(!appr.value && !C.rn2(++chcnt, 1970, "m_move"))))
                || (C.bool(appr.value == -2
                    && (C.bool((C.bool(ndist <= preferredrange_min.value && !nearer))
                        || (C.bool(ndist >= preferredrange_max.value && nearer)))))))
                || (mmoved.value == C.MMOVE_NOTHING))) {
                nix = C.coordxy(nx);
                niy = C.coordxy(ny);
                nidist = C.int(ndist);
                chi = C.int(i);
                mmoved.value = C.MMOVE_MOVED;
            }
        }
    }

    if (mmoved.value != C.MMOVE_NOTHING) {
        if (C.bool(C.bool(mmoved.value == C.MMOVE_MOVED && !C.u_at(nix, niy)) && itsstuck(mtmp)))
            return C.MMOVE_DONE;

        if (C.bool(mmoved.value == C.MMOVE_MOVED && m_digweapon_check(mtmp, nix, niy)))
            return C.MMOVE_DONE;

        /* If ALLOW_U is set, either it's trying to attack you, or it
         * thinks it is.  In either case, attack this spot in preference to
         * all others.
         */
        /* Actually, this whole section of code doesn't work as you'd expect.
         * Most attacks are handled in dochug().  It calls distfleeck(), which
         * among other things sets nearby if the monster is near you--and if
         * nearby is set, we never call m_move unless it is a special case
         * (confused, stun, etc.)  The effect is that this ALLOW_U (and
         * mfndpos) has no effect for normal attacks, though it lets a
         * confused monster attack you by accident.
         */
        C.assert(C.IndexOk(chi, mfp.info));
        if (mfp.info[chi] & C.ALLOW_U) {
            nix = C.coordxy(mtmp.mux);
            niy = C.coordxy(mtmp.muy);
        }
        if (C.u_at(nix, niy)) {
            mtmp.mux = C.u.ux;
            mtmp.muy = C.u.uy;
            return C.MMOVE_NOTHING;
        }
        /* The monster may attack another based on 1 of 2 conditions:
         * 1 - It may be confused.
         * 2 - It may mistake the monster for your (displaced) image.
         * Pets get taken care of above and shouldn't reach this code.
         * Conflict gets handled even farther away (movemon()).
         */
        if (C.bool((mfp.info[chi] & C.ALLOW_M) != 0
            || (C.bool(nix == mtmp.mux && niy == mtmp.muy))))
            return m_move_aggress(mtmp, nix, niy);

        if ((mfp.info[chi] & C.ALLOW_MDISP) != 0) {
            let mtmp2;
            let mstatus;

            mtmp2 = C.m_at(nix, niy); /* ALLOW_MDISP implies m_at() is !Null */
            mstatus = C.int(C.mdisplacem(mtmp, mtmp2, 0));
            /*[if either dies, this reports mtmp has died; is that correct?]*/
            if (mstatus & (C.M_ATTK_AGR_DIED | C.M_ATTK_DEF_DIED))
                return C.MMOVE_DIED;
            if (mstatus & C.M_ATTK_HIT)
                return C.MMOVE_MOVED;
            return C.MMOVE_DONE;
        }

        if (!C.m_in_out_region(mtmp, nix, niy))
            return C.MMOVE_DONE;

        if (C.bool((mfp.info[chi] & C.ALLOW_ROCK) && m_can_break_boulder(mtmp))) {
            m_break_boulder(mtmp, nix, niy);
            return C.MMOVE_DONE;
        }

        m_postmove_effect(mtmp);

        /* move a normal monster; for a long worm, remove_monster() and
           place_monster() only manipulate the head; they leave tail as-is */
        C.remove_monster(omx, omy);
        C.place_monster(mtmp, nix, niy);
        msg_mon_movement(mtmp, omx, omy);
        /* for a long worm, insert a new segment to reconnect the head
           with the tail; worm_move() keeps the end of the tail if worm
           is scheduled to grow, removes that for move-without-growing */
        if (mtmp.wormno)
            C.worm_move(mtmp);

        C.maybe_unhide_at(mtmp.mx, mtmp.my);

        mon_track_add(mtmp, omx, omy);
    } else {
        if (C.bool(C.bool(C.is_unicorn(ptr) && C.rn2(2, 2064, "m_move")) && !C.tele_restrict(mtmp))) {
            C.rloc(mtmp, C.RLOC_MSG);
            return C.MMOVE_MOVED;
        }
        /* for a long worm, shrink it (by discarding end of tail) when
           it has failed to move */
        if (mtmp.wormno)
            C.worm_nomove(mtmp);
    }
    return postmov(mtmp, ptr, omx, omy, mmoved.value,
                   seenflgs, can_tunnel, can_unlock, can_open);
}

/* The part of m_move that deals with a monster attacking another monster (and
 * that monster possibly retaliating).
 * Extracted into its own function so that it can be called with monsters that
 * have special move patterns (shopkeepers, priests, etc) that want to attack
 * other monsters but aren't just roaming freely around the level (so allowing
 * m_move to run fully for them could select an invalid move).
 * x and y are the coordinates mtmp wants to attack.
 * Return values are the same as for m_move, but this function only return 2
 * (mtmp died) or 3 (mtmp made its move).
 */
function m_move_aggress(mtmp, x, y)

{
    x = C.coordxy(C.coordxy(x)); y = C.coordxy(C.coordxy(y));
    let mtmp2;
    let mstatus = C.int(0); /* M_ATTK_MISS */

    mtmp2 = C.m_at(x, y);
    if (mtmp2) {
        C.gb.bhitpos.x = x, C.gb.bhitpos.y = y;
        C.gn.notonhead = (C.bool(x != mtmp2.mx || y != mtmp2.my));
        mstatus = C.int(C.mattackm(mtmp, mtmp2));
    }

    if (C.bool((mstatus & C.M_ATTK_AGR_DIED) || C.DEADMONSTER(mtmp))) /* aggressor died */
        return C.MMOVE_DIED;

    if (C.bool(C.bool((mstatus & (C.M_ATTK_HIT | C.M_ATTK_DEF_DIED)) == C.M_ATTK_HIT
        && C.rn2(4, 2104, "m_move_aggress")) && mtmp2.movement > C.rn2(C.NORMAL_SPEED, 2104, "m_move_aggress"))) {
        if (mtmp2.movement > C.NORMAL_SPEED)
            mtmp2.movement -= C.NORMAL_SPEED;
        else
            mtmp2.movement = 0;
        C.gb.bhitpos.x = mtmp.mx, C.gb.bhitpos.y = mtmp.my;
        C.gn.notonhead = 0;
        mstatus = C.int(C.mattackm(mtmp2, mtmp)); /* return attack */
        /* note: at this point, defender is the original (moving) aggressor */
        if (mstatus & C.M_ATTK_DEF_DIED)
            return C.MMOVE_DIED;
    }
    return C.MMOVE_DONE;
}

/* returns TRUE if a mon can hide under the obj */
function can_hide_under_obj(obj)

{
/* uncomment '#define NO_HIDING_UNDER_STATUES' to prevent hiding under
 * statues; that was introduced to avoid nullifying statue traps but
 * isn't needed now that hiding at any non-pit trap site is disallowed */
/* #define NO_HIDING_UNDER_STATUES */
    let t;

    if (C.bool(!obj || obj.where != C.OBJ_FLOOR))
        return 0;
    /* can't hide in/on/under traps (except pits) even when there is an
       object here; since obj is on floor, its <ox,oy> are up to date */
    if (C.bool((t = C.t_at(obj.ox, obj.oy)) != 0 && !C.is_pit(t.ttyp)))
        return 0;
    /* can't hide under small amount of coins unless non-coins are also
       present; we expect coins to be a single stack but don't assume that */
    if (obj.oclass == C.COIN_CLASS) {
        let coinquan = C.long(0n);

        do {
            /* 10 coins is arbitrary amount considered enough to hide under */
            if ((coinquan = C.long(coinquan + (obj.quan))) >= 10n)
                break; /* fall through to other checks */
            obj = obj.nexthere;
            if (!obj)
                return 0; /* whole pile was less than 10 coins */
        } while (obj.oclass == C.COIN_CLASS);
    }
/*
     * 'obj' might have been changed, but only if we've skipped coins that
     * are on the top of a pile.  However, the statue loop will clobber it.
     */
/* can't hide under statues regardless of pile stacking order */
/*
     * If we reach here, 'obj' is now Null but wasn't earlier so the original
     * 'obj' can be hidden beneath.
     */

    return 1; /* can hide under the object */
}

function dissolve_bars(x, y)

{
    x = C.coordxy(C.coordxy(x)); y = C.coordxy(C.coordxy(y));
    C.levl[x][y].typ = (C.levl[x][y].edge == 1) ? C.DOOR
        : (C.bool(C.Is_special(C.u.uz) || C.loadChar(C.in_rooms(x, y, 0)))) ? C.ROOM : C.CORR;
    C.levl[x][y].flags = 0; /* doormask = D_NODOOR */
    C.newsym(x, y);
    if (C.u_at(x, y))
        C.switch_terrain();
}

function closed_door(x, y)

{
    x = C.coordxy(C.coordxy(x)); y = C.coordxy(C.coordxy(y));
    return C.boolean((C.bool(C.IS_DOOR(C.levl[x][y].typ)
                      && (C.levl[x][y].doormask & (C.D_LOCKED | C.D_CLOSED)))));
}

function accessible(x, y)

{
    x = C.coordxy(C.coordxy(x)); y = C.coordxy(C.coordxy(y));
    /* use underlying terrain in front of closed drawbridge */
    let levtyp = C.int(C.SURFACE_AT(x, y));

    return C.boolean((C.bool(C.ACCESSIBLE(levtyp) && !closed_door(x, y))));
}

/* decide where the monster thinks you are standing */
function set_apparxy(mtmp)

{
    let notseen, notthere, gotu;
    let displ;
    let mx = C.coordxy(mtmp.mux), my = C.coordxy(mtmp.muy);
    let umoney = C.long(C.money_cnt(C.gi.invent));

    /*
     * do cheapest and/or most likely tests first
     */

    /* pet knows your smell; grabber still has hold of you; monsters which
       know where you are don't suddenly forget, if you haven't moved away */
    if (C.bool(C.bool(mtmp.mtame || C.samePtr(mtmp, C.u.ustuck)) || C.u_at(mx, my))) {
            mtmp.mux = C.u.ux;
            mtmp.muy = C.u.uy;
            return;
    }

    notseen = C.char(C.bool(!mtmp.mcansee || (C.bool(C.Invis && !C.perceives(mtmp.data)))));
    notthere = C.char(C.bool(C.Displaced && !C.samePtr(mtmp.data, C.mons[C.PM_DISPLACER_BEAST])));
    /* add cases as required.  eg. Displacement ... */
    if (C.Underwater) {
        displ = C.int(1);
    } else if (notseen) {
        /* Xorns can smell quantities of valuable metal
           like that in solid gold coins, treat as seen */
        displ = C.int((C.bool(C.samePtr(mtmp.data, C.mons[C.PM_XORN]) && umoney)) ? 0 : 1);
    } else if (notthere) {
        displ = C.int(C.couldsee(mx, my) ? 2 : 1);
    } else {
        displ = C.int(0);
    }
    if (!displ) {
        mtmp.mux = C.u.ux;
        mtmp.muy = C.u.uy;
        return;
    }

    /* without something like the following, invisibility and displacement
       are too powerful */
    gotu = C.char(notseen ? !C.rn2(3, 2239, "set_apparxy") : notthere ? !C.rn2(4, 2239, "set_apparxy") : 0);

    if (!gotu) {
        let try_cnt = C.int(0);

        do {
            if (++try_cnt > 200) {
                mx = C.coordxy(C.u.ux);
                my = C.coordxy(C.u.uy);
                break; /* punt */
            }
            mx = C.coordxy(C.u.ux - displ + C.rn2(2 * displ + 1, 2250, "set_apparxy"));
            my = C.coordxy(C.u.uy - displ + C.rn2(2 * displ + 1, 2251, "set_apparxy"));
        } while (C.bool(C.bool(C.bool(!C.isok(mx, my)
                 || (C.bool(C.bool(displ != 2 && mx == mtmp.mx) && my == mtmp.my)))
                 || (C.bool(C.bool((C.bool(mx != C.u.ux || my != C.u.uy)) && !C.passes_walls(mtmp.data))
                     && !(C.bool(accessible(mx, my)
                          || (C.bool(closed_door(mx, my)
                              && (C.bool(can_ooze(mtmp) || can_fog(mtmp))))))))))
                 || !C.couldsee(mx, my)));
    } else {
        mx = C.coordxy(C.u.ux);
        my = C.coordxy(C.u.uy);
    }

    mtmp.mux = mx;
    mtmp.muy = my;
}

/*
 * mon-to-mon displacement is a deliberate "get out of my way" act,
 * not an accidental bump, so we don't consider mstun or mconf in
 * undesired_disp().
 *
 * We do consider many other things about the target and its
 * location however.
 */
function undesirable_disp(mtmp, x, y)
 /* spot 'mtmp' is considering moving to */
{
    x = C.coordxy(C.coordxy(x)); y = C.coordxy(C.coordxy(y));
    let is_pet = (C.char(C.bool(mtmp.mtame && !mtmp.isminion)));
    let trap = C.t_at(x, y);

    if (is_pet) {
        /* Pets avoid a trap if you've seen it usually. */
        if (C.bool(C.bool(trap && trap.tseen) && C.rn2(40, 2287, "undesirable_disp")))
            return 1;
        /* Pets avoid cursed locations */
        if (C.cursed_object_at(x, y))
            return 1;

    /* Monsters avoid a trap if they've seen that type before */
    } else if (C.bool(C.bool(trap && C.rn2(40, 2294, "undesirable_disp"))
               && C.mon_knows_traps(mtmp, trap.ttyp))) {
        return 1;
    }

    /* oversimplification:  creatures that bargethrough can't swap places
       when target monster is in rock or closed door or water (in particular,
       avoid moving to spots where mondied() won't leave a corpse; doesn't
       matter whether barger is capable of moving to such a target spot if
       it were unoccupied) */
    if (C.bool(!accessible(x, y)
        /* mondied() allows is_pool() as an exception to !accessible(),
           but we'll only do that if 'mtmp' is already at a water location
           so that we don't swap a water critter onto land */
        && !(C.bool(C.is_pool(x, y) && C.is_pool(mtmp.mx, mtmp.my)))))
        return 1;

    return 0;
}

/*
 * Inventory prevents passage under door.
 * Used by can_ooze() and can_fog().
 */
function stuff_prevents_passage(mtmp)

{
    let chain, obj;

    if (C.samePtr(mtmp, C.gy.youmonst)) {
        chain = C.gi.invent;
    } else {
        chain = mtmp.minvent;
    }
    for (obj = chain; obj; obj = obj.nobj) {
        let typ = C.int(obj.otyp);

        if (C.bool(typ == C.COIN_CLASS && obj.quan > 100n))
            return 1;
        if (C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(C.bool(obj.oclass != C.GEM_CLASS && !(C.bool(typ >= C.ARROW && typ <= C.BOOMERANG)))
            && !(C.bool(typ >= C.DAGGER && typ <= C.CRYSKNIFE))) && typ != C.SLING)
            && !C.is_cloak(obj)) && typ != C.FEDORA) && !C.is_gloves(obj))
            && typ != C.LEATHER_JACKET) && typ != C.CREDIT_CARD) && !C.is_shirt(obj))
            && !(C.bool(typ == C.CORPSE && C.verysmall(C.mons[obj.corpsenm]))))
            && typ != C.FORTUNE_COOKIE) && typ != C.CANDY_BAR) && typ != C.PANCAKE)
            && typ != C.LEMBAS_WAFER) && typ != C.LUMP_OF_ROYAL_JELLY)
            && obj.oclass != C.AMULET_CLASS) && obj.oclass != C.RING_CLASS)
            && obj.oclass != C.VENOM_CLASS) && typ != C.SACK)
            && typ != C.BAG_OF_HOLDING) && typ != C.BAG_OF_TRICKS)
            && !C.Is_candle(obj)) && typ != C.OILSKIN_SACK) && typ != C.LEASH)
            && typ != C.STETHOSCOPE) && typ != C.BLINDFOLD) && typ != C.TOWEL)
            && typ != C.TIN_WHISTLE) && typ != C.MAGIC_WHISTLE)
            && typ != C.MAGIC_MARKER) && typ != C.TIN_OPENER) && typ != C.SKELETON_KEY)
            && typ != C.LOCK_PICK))
            return 1;
        if (C.bool(C.Is_container(obj) && obj.cobj))
            return 1;
    }
    return 0;
}

function can_ooze(mtmp)

{
    if (C.bool(!C.amorphous(mtmp.data) || stuff_prevents_passage(mtmp)))
        return 0;
    return 1;
}

/* monster can change form into a fog if necessary */
function can_fog(mtmp)

{
    if (C.bool(C.bool(C.bool(!(C.svm.mvitals[C.PM_FOG_CLOUD].mvflags & C.G_GENOD) && C.is_vampshifter(mtmp))
        && !C.Protection_from_shape_changers) && !stuff_prevents_passage(mtmp)))
        return 1;
    return 0;
}

/* this is called when a vampire turns into a fog cloud in order to move
   under a closed door; if it was sensed via telepathy or seen via
   infravision, its new fog cloud shape will disappear */
function vamp_shift(mon, ptr, domsg)

{
    domsg = C.char(C.boolean(domsg));
    let reslt = C.int(0);

    if (C.samePtr(mon.data, ptr)) {
        /* already right shape */
        reslt = C.int(1);
    } else if (C.is_vampshifter(mon)) {
        reslt = C.int(C.newcham(mon, ptr, domsg ? C.NC_SHOW_MSG : C.NO_NC_FLAGS));
        /* shape-change message is given when vampshifter turns into a
           fog cloud in order to move under a closed door */
        C.display_nhwindow(C.WIN_MESSAGE, 0);
    }
    return reslt;
}

